@page "/board"
@using sv_396aa48ef30c40eeab1393b9ccb10348.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<div class="board-page">
    @if (isLoading)
    {
        <p class="loading-message">Loading tasks...</p>
    }
    else if (errorMessage is not null)
    {
        <p class="error-message">@errorMessage</p>
    }
    else
    {
        <BoardStats Tasks="allTasks" />
        <TaskSearch SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

        <div class="kanban-board">
            <KanbanColumn Title="To Do" Status="To Do"
                          Tasks="GetFilteredTasks("To Do")"
                          ShowMoveLeft="false" ShowMoveRight="true"
                          OnMoveRight="task => MoveTask(task, "In Progress")"
                          OnTaskCreated="HandleTaskCreated" />

            <KanbanColumn Title="In Progress" Status="In Progress"
                          Tasks="GetFilteredTasks("In Progress")"
                          ShowMoveLeft="true" ShowMoveRight="true"
                          OnMoveLeft="task => MoveTask(task, "To Do")"
                          OnMoveRight="task => MoveTask(task, "Done")"
                          OnTaskCreated="HandleTaskCreated" />

            <KanbanColumn Title="Done" Status="Done"
                          Tasks="GetFilteredTasks("Done")"
                          ShowMoveLeft="true" ShowMoveRight="false"
                          OnMoveLeft="task => MoveTask(task, "In Progress")"
                          OnTaskCreated="HandleTaskCreated" />
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleTaskCreated(TaskItem taskInfo)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(taskInfo.Title, taskInfo.Assignee, taskInfo.Priority, taskInfo.DueDate);
            allTasks.Add(created);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

.board-page {
    padding: 1rem;
    max-width: 1400px;
    margin: 0 auto;
}

.loading-message,
.error-message {
    text-align: center;
    padding: 2rem;
    font-size: 1.1rem;
}

.error-message {
    color: #dc3545;
}

/* Stats Bar */
.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
}

.stat-item {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-label {
    font-size: 0.8rem;
    color: #6c757d;
    text-transform: uppercase;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: bold;
}

.stat-overdue .stat-value {
    color: #dc3545;
}

/* Search */
.task-search {
    margin-bottom: 1rem;
}

.task-search input {
    width: 100%;
    padding: 0.5rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    font-size: 1rem;
}

/* Kanban Board */
.kanban-board {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 1rem;
}

/* Column */
.kanban-column {
    background: #f1f3f5;
    border-radius: 8px;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    min-height: 400px;
}

.column-header h3 {
    margin: 0 0 0.75rem 0;
    font-size: 1rem;
    color: #495057;
}

.column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.column-footer {
    margin-top: 0.75rem;
}

/* Task Card */
.task-card {
    background: #ffffff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.75rem;
}

.task-title {
    margin: 0 0 0.25rem 0;
    font-size: 0.95rem;
}

.task-assignee {
    margin: 0 0 0.5rem 0;
    font-size: 0.85rem;
    color: #6c757d;
}

.priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

.priority-high {
    background: #f8d7da;
    color: #842029;
}

.priority-medium {
    background: #fff3cd;
    color: #664d03;
}

.priority-low {
    background: #d1e7dd;
    color: #0f5132;
}

.task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

.task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    padding: 0.2rem 0.5rem;
    font-size: 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    background: #ffffff;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

/* Add Task */
.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    border: 1px dashed #adb5bd;
    border-radius: 6px;
    background: transparent;
    color: #6c757d;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.add-task-form input,
.add-task-form select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-save {
    padding: 0.4rem 0.8rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.btn-cancel {
    padding: 0.4rem 0.8rem;
    background: #6c757d;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

